		dupOnce(`"status":"`+StatusPass+`"`,
			`"status":"`+StatusPass+`","status":"`+StatusPass+`"`))
	expectCorruptDupLoad(t, dir, id, `"status"`, `rule "r-pass"`, "rules[0]")
}

