	dir := t.TempDir()
	id := writeDupArchiveText(t, dir, oneDefectFixture(),
		dupOnce(`"artifact":{"name":"Vault"`,
			`"artifact":{"name":"Other","name":"Vault"`))
	expectCorruptDupLoad(t, dir, id, `"name"`, "the artifact object")
}

