	dir := t.TempDir()
	r := oneDefectFixture()
	r.ReportID = ReportID(r)
	id := writeDupArchiveText(t, dir, r, func(doc string) string {
		old := `"reportId":"` + r.ReportID + `"`
		return strings.Replace(doc, old, old+","+old, 1)
	})
	expectCorruptDupLoad(t, dir, id, `"reportId"`, "the top-level object")
