20	// auditOneReport 通过真实 audit 命令落盘一份合法的混合状态报告，返回其标识。
21	func auditOneReport(t *testing.T, bin, work, store string) string {
22		t.Helper()
23		input := writeStructInput(t, work, "in.json", mixedCheckInput(mixedArtifactHash(t)))
24		stdout, stderr, code := runCLIAudit(t, bin, input, store)
25		if code != 0 {
26			t.Fatalf("setup audit must succeed: %s", stderr)
27		}
28		return decodeReport(t, stdout).ReportID
29	}
30	
31	// injectArchiveDuplicate reads the archive named by id, applies the textual
32	// replacement once, and writes it back. All replacements repeat a member
33	// while leaving the last value identical to the legal one.
34	func injectArchiveDuplicate(t *testing.T, store, id, old, new string) {
35		t.Helper()
36		path := filepath.Join(store, id+".json")
37		data, err := os.ReadFile(path)
38		if err != nil {
39			t.Fatal(err)
40		}
41		doc := string(data)
42		if !strings.Contains(doc, old) {
43			t.Fatalf("test setup: archive does not contain %q", old)
44		}
45		doc = strings.Replace(doc, old, new, 1)
46		if err := os.WriteFile(path, []byte(doc), 0o644); err != nil {
47			t.Fatal(err)
48		}
49	}
50	
51	// runCLIDiff-like helpers already exist; assert the full failure contract here.
52	func assertDupFailure(t *testing.T, stdout, stderr string, code int, id string, want ...string) {
53		t.Helper()
54		if code == 0 {
55			t.Fatal("an archive with a duplicate JSON member must exit non-zero")
56		}
57		if !strings.Contains(strings.ToLower(stderr), "duplicate") {
58			t.Fatalf("stderr must state that a member is duplicated:\n%s", stderr)
59		}
60		if !strings.Contains(stderr, "corrupt") {
61			t.Fatalf("stderr must classify the archive as corrupt:\n%s", stderr)
62		}
63		if !strings.Contains(stderr, id) {
64			t.Fatalf("stderr must name the report id %q:\n%s", id, stderr)
65		}
66		for _, w := range want {
67			if !strings.Contains(stderr, w) {
68				t.Fatalf("stderr must contain %q:\n%s", w, stderr)
69			}
70		}
71		if stdout != "" {
72			t.Fatalf("rejected read must print nothing to stdout, got:\n%s", stdout)
73		}
74	}
75	
76	// --- report：规则中先“发现缺陷”再“通过”，最后一个值使标识仍一致，仍须拒绝 ---
77	
78	func TestCLIReportDuplicateRuleStatusRejected(t *testing.T) {
79		bin := auditBinary(t)
80		work := t.TempDir()
81		store := filepath.Join(work, "reports")
82		id := auditOneReport(t, bin, work, store)
83		injectArchiveDuplicate(t, store, id,
84			`"status":"`+contractsentinel.StatusPass+`"`,
85			`"status":"`+contractsentinel.StatusDefect+`","status":"`+contractsentinel.StatusPass+`"`)
86	
87		stdout, stderr, code := runCLIReport(t, bin, store, id)
88		assertDupFailure(t, stdout, stderr, code, id, `"status"`, `rule "rule-pass"`, "rules[0]")
89	
90		// 原文件必须原样保留。
91		data, err := os.ReadFile(filepath.Join(store, id+".json"))
92		if err != nil {
93			t.Fatal(err)
94		}
95		if !strings.Contains(string(data), `"status":"`+contractsentinel.StatusDefect+`","status":"`+contractsentinel.StatusPass+`"`) {
96			t.Fatal("failed report read must leave the corrupt archive untouched")
97		}
98	}
99	
100	// --- report：两个值完全相同也不接受 ---
101	
102	func TestCLIReportDuplicateEqualValuesRejected(t *testing.T) {
103		bin := auditBinary(t)
104		work := t.TempDir()
105		store := filepath.Join(work, "reports")
106		id := auditOneReport(t, bin, work, store)
107		injectArchiveDuplicate(t, store, id,
108			`"id":"rule-defect"`,
109			`"id":"rule-defect","id":"rule-defect"`)
110	
111		stdout, stderr, code := runCLIReport(t, bin, store, id)
112		assertDupFailure(t, stdout, stderr, code, id, `"id"`, `rule "rule-defect"`, "rules[1]")
113	}
114	
115	// --- report：缺陷记录数组中的重复成员，给出位置与涉及规则 ---
116	
117	func TestCLIReportDuplicateFindingMemberRejected(t *testing.T) {
118		bin := auditBinary(t)
119		work := t.TempDir()
120		store := filepath.Join(work, "reports")
121		id := auditOneReport(t, bin, work, store)
122		injectArchiveDuplicate(t, store, id,
123			`"ruleId":"rule-defect"`,
124			`"ruleId":"rule-defect","ruleId":"rule-defect"`)
125	
126		stdout, stderr, code := runCLIReport(t, bin, store, id)
127		assertDupFailure(t, stdout, stderr, code, id, `"ruleId"`, `finding for rule "rule-defect"`, "findings[0]")
128	}
