136		id := auditOneReport(t, bin, work, store)
137		injectArchiveDuplicate(t, store, id,
138			`"name":"Vault"`,
139			`"name":"Other","name":"Vault"`)
140	
141		stdout, stderr, code := runCLIReport(t, bin, store, id)
142		assertDupFailure(t, stdout, stderr, code, id, `"name"`, "the artifact object")
