61			{ArtifactHash: hash, RuleID: "a-resolved", Version: "1", Status: contractsentinel.StatusPass},
62			{ArtifactHash: hash, RuleID: "b-tool-to-pass", Version: "2", Status: contractsentinel.StatusPass},
63			{ArtifactHash: hash, RuleID: "c-unchecked-to-pass", Version: "3", Status: contractsentinel.StatusPass},
64			{ArtifactHash: hash, RuleID: "m-timeout-to-defect", Version: "7", Status: contractsentinel.StatusDefect, Note: defectNote},
65			{ArtifactHash: hash, RuleID: "n-defect-to-timeout", Version: "8", Status: contractsentinel.StatusTimeout, Note: "复跑超过 60s 截止时间"},
66			{ArtifactHash: hash, RuleID: "d-stable-defect", Version: "4", Status: contractsentinel.StatusDefect, Note: "稳定缺陷证据"},
