71	// auditDiffReport 用给定规则与检查记录通过真实 audit 命令落盘一份报告并解码返回。
72	func auditDiffReport(t *testing.T, bin, work, store, name string, artifact cliWireArtifact, rules []cliWireRule, checks []cliWireCheck) contractsentinel.Report {
73		t.Helper()
74		in := cliWireInput{Artifact: artifact, Rules: rules, Checks: checks}
75		input := writeStructInput(t, work, name, in)
76		stdout, stderr, code := runCLIAudit(t, bin, input, store)
77		if code != 0 {
78			t.Fatalf("setup audit %s must succeed, exit=%d stderr=%s", name, code, stderr)
79		}
80		return decodeReport(t, stdout)
81	}
82	
83	// runCLIDiff 在真实进程上运行 diff，返回 stdout、stderr 与退出码。
84	func runCLIDiff(t *testing.T, bin, store, before, after string) (string, string, int) {
85		t.Helper()
86		cmd := exec.Command(bin, "diff", "--store", store, "--before", before, "--after", after)
87		var stdout, stderr bytes.Buffer
88		cmd.Stdout = &stdout
89		cmd.Stderr = &stderr
90		err := cmd.Run()
91		if err == nil {
92			return stdout.String(), stderr.String(), 0
93		}
94		if exitErr, ok := err.(*exec.ExitError); ok {
95			return stdout.String(), stderr.String(), exitErr.ExitCode()
96		}
97		t.Fatalf("failed to start diff: %v", err)
98		return "", "", 0
99	}
100	
101	func decodeDiff(t *testing.T, raw string) contractsentinel.DiffResult {
102		t.Helper()
103		var d contractsentinel.DiffResult
104		if err := json.Unmarshal([]byte(raw), &d); err != nil {
105			t.Fatalf("diff output is not parseable JSON: %v\n%s", err, raw)
106		}
107		return d
108	}
