110	func diffEntry(t *testing.T, d contractsentinel.DiffResult, ruleID string) contractsentinel.RuleDiff {
111		t.Helper()
112		for _, r := range d.Results {
113			if r.RuleID == ruleID {
114				return r
115			}
116		}
117		t.Fatalf("diff result for rule %s not found", ruleID)
118		return contractsentinel.RuleDiff{}
119	}
