	}
	if !strings.Contains(err.Error(), id) || !strings.Contains(err.Error(), "r-pass") ||
		!strings.Contains(err.Error(), "requiresABI must be a boolean") {
		t.Fatalf("error must name the report, rule and boolean requirement: %v", err)
	}
